export const RARITY_ICON_FILE: Record<'S' | 'A', string> = {
  "S": "ItemRarityS.png",
  "A": "ItemRarityA.png"
};

export function agentSelectIconUrl(name: string | undefined | null): string | null {
  if (!name) return null;
  const f = AGENT_SELECT_ICON[name] || AGENT_SELECT_ICON[name.replace(/[「」]/g, '')];
  return f ? `/resources/agent-icons/${f}` : null;
}

export function agentCircleIconUrl(name: string | undefined | null): string | null {
  if (!name) return null;
  const f = AGENT_CIRCLE_ICON[name] || AGENT_CIRCLE_ICON[name.replace(/[「」]/g, '')];
  return f ? `/resources/agent-icons/${f}` : null;
}

export function elementIconUrl(element: string | undefined | null): string | null {
  if (!element) return null;
  const f = ELEMENT_ICON_FILE[element];
  return f ? `/resources/ui-icons/${f}` : null;
}

export function professionIconUrl(prof: string | undefined | null): string | null {
  if (!prof) return null;
  const f = PROFESSION_ICON_FILE[prof];
  return f ? `/resources/ui-icons/${f}` : null;
}

export function rarityIconUrl(rarity: string | undefined | null): string | null {
  if (rarity !== 'S' && rarity !== 'A') return null;
  return `/resources/ui-icons/${RARITY_ICON_FILE[rarity]}`;
}
